/// <summary>
/// Determines if concurrent deletes should throw exception.
/// </summary>
/// <returns>true, if exception should be thrown; otherwise, false.</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    return true;
}

public void initValue()
{
    super();

    if (!this.ExtractionId)
    {
        this.ExtractionId = NumberSeq::newGetNum(NumberSeqReference::findReference(extendedTypeNum(METSalesOrderExtractionId))).num();
    }
}

static boolean exist(METSalesOrderExtractionId _extractionId)
{
    METSalesOrderExtractionTable salesOrderExtractionTable;

    if (_extractionId)
    {
        select firstonly RecId 
            from salesOrderExtractionTable
            where salesOrderExtractionTable.ExtractionId == _extractionId;
    }

    return salesOrderExtractionTable.RecId != 0;
}

static METSalesOrderExtractionTable find(METSalesOrderExtractionId   _extractionId,
                      boolean       _forUpdate = false)
{
    METSalesOrderExtractionTable salesOrderExtractionTable;

    if (_extractionId)
    {
        if (_forUpdate)
        {
            salesOrderExtractionTable.selectForUpdate(_forUpdate);
        }

        select firstonly salesOrderExtractionTable
            where salesOrderExtractionTable.ExtractionId == _extractionId;
    }

    return salesOrderExtractionTable;
}

/// <summary>
/// Rolls up ExtractionStatus to the lowest in-flight status on the lines. Completed is
/// excluded - that stays finalizeExtractionHeader()'s alone.
/// </summary>
public void updateStatus()
{
    #define.StatusPriorityOrder([
        METSalesOrderExtractionStatus::Pending,
        METSalesOrderExtractionStatus::Processing,
        METSalesOrderExtractionStatus::Failed])

    METSalesOrderExtractionLine    extractionLine;
    Set                             lineStatusSet = new Set(Types::Enum);
    container                       priorityOrder = #StatusPriorityOrder;
    METSalesOrderExtractionStatus   lowestStatus;
    boolean                         found;
    int                              i;

    while select ExtractionStatus from extractionLine
        group by ExtractionStatus
        where extractionLine.ExtractionId == this.ExtractionId
    {
        lineStatusSet.add(extractionLine.ExtractionStatus);
    }

    for (i = 1; i <= conLen(priorityOrder) && !found; i++)
    {
        METSalesOrderExtractionStatus candidate = conPeek(priorityOrder, i);

        if (lineStatusSet.in(candidate))
        {
            lowestStatus = candidate;
            found        = true;
        }
    }

    if (found && this.ExtractionStatus != lowestStatus)
    {
        this.ExtractionStatus = lowestStatus;
        this.update();
    }
}
